  1	import { Logger } from "@nestjs/common";
  2	import { Transaction } from "../transactions/entities/transaction.entity";
  3	import { TransactionSplit } from "../transactions/entities/transaction-split.entity";
  4	import { ImportContext } from "./import-context";
  5	import { holdKey } from "./ofx-external-id";
  6	
  7	/**
  8	 * How the import tells a transfer line of the file apart from a transfer the
  9	 * account already records, so a second download or the other account's file
 10	 * does not write the transfer twice.
 11	 *
 12	 * A line without a bank id is matched by signature (date, amount, the other
 13	 * account) and counted: two genuinely different transfers can share one, so a
 14	 * line is a duplicate only while the lines of that signature seen so far do not
 15	 * outnumber the rows recorded (`isDuplicateTransfer`). A line with a bank id
 16	 * (OFX `FITID`) is not counted against other rows: it takes over the bank id
 17	 * on one recorded transfer that has none (`adoptKeyOnRecordedTransfer`), so
 18	 * each line claims its own row whatever order the file lists them in, and its
 19	 * next download is skipped by the key.
 20	 */
 21	
 22	/** The account a transfer line names, by name and then case-insensitively. */
 23	function transferAccountIdOf(
 24	  ctx: ImportContext,
 25	  transferAccount: string,
 26	): string | undefined {
 27	  const exact = ctx.accountMap.get(transferAccount) ?? undefined;
 28	  if (exact) return exact;
 29	  const lowerName = transferAccount.toLowerCase();
 30	  for (const [name, id] of ctx.accountMap) {
 31	    if (id && name.toLowerCase() === lowerName) return id;
 32	  }
 33	  return undefined;
 34	}
 35	
 36	/**
 37	 * The counter keys of a transfer line: one per kind of recorded transfer it is
 38	 * matched against (a linked leg, a split-linked row).
 39	 */
 40	function transferSignatureKeys(ctx: ImportContext, qifTx: any): string[] {
 41	  if (!qifTx.isTransfer) return [];
 42	  const keys: string[] = [];
 43	  const transferAccountId = qifTx.transferAccount
 44	    ? transferAccountIdOf(ctx, qifTx.transferAccount)
 45	    : undefined;
 46	  if (transferAccountId) {
 47	    keys.push(`linked|${qifTx.date}|${qifTx.amount}|${transferAccountId}`);
 48	  }
 49	  keys.push(`split|${qifTx.date}|${qifTx.amount}`);
 50	  return keys;
 51	}
 52	
 53	/** Raise a counter and answer how many lines it had counted before. */
 54	function bumpSignature(ctx: ImportContext, sigKey: string): number {
 55	  const seenSoFar = ctx.transferDupCounts.get(sigKey) || 0;
 56	  ctx.transferDupCounts.set(sigKey, seenSoFar + 1);
 57	  return seenSoFar;
 58	}
 59	
 60	/**
 61	 * Give a transfer line that carries a bank id its turn in the signature
 62	 * counters, without the counted queries. The line names a row the account
 63	 * holds (by its key, or the one it adopts) or one it is about to write, and
 64	 * the counted queries of a later line without a bank id see that row either
 65	 * way, so the line must be counted as seen.
 66	 */
 67	export function countTransferTurn(ctx: ImportContext, qifTx: any): void {
 68	  for (const sigKey of transferSignatureKeys(ctx, qifTx)) {
 69	    bumpSignature(ctx, sigKey);
 70	  }
 71	}
 72	
 73	/**
 74	 * Whether a transfer line without a bank id is already recorded, from a prior
 75	 * import or an earlier account block, by counting (see the module comment).
 76	 */
 77	export async function isDuplicateTransfer(
 78	  ctx: ImportContext,
 79	  qifTx: any,
 80	  logger: Logger,
 81	): Promise<boolean> {
 82	  // Check for duplicate linked transfers using counting to avoid false positives.
 83	  // Multiple genuinely different transfers can share the same date, amount, and
 84	  // account pair (e.g. two $150 transfers to the same account on the same day
 85	  // with different payees). We count how many matching linked transfers already
 86	  // exist in the DB and how many same-signature QIF entries we have seen in this
 87	  // block; only skip when the seen count does not exceed the existing count.
 88	  if (qifTx.isTransfer && qifTx.transferAccount) {
 89	    const mappedTransferAccountId = transferAccountIdOf(
 90	      ctx,
 91	      qifTx.transferAccount,
 92	    );
 93	    if (mappedTransferAccountId) {
 94	      const existingCount = await ctx.manager
 95	        .createQueryBuilder(Transaction, "t")
 96	        .innerJoin(Transaction, "linked", "t.linked_transaction_id = linked.id")
 97	        .where("t.user_id = :userId", { userId: ctx.userId })
 98	        .andWhere("t.account_id = :accountId", {
 99	          accountId: ctx.accountId,
100	        })
101	        .andWhere("t.is_transfer = true")
102	        .andWhere("t.transaction_date = :date", { date: qifTx.date })
103	        .andWhere("t.amount = :amount", { amount: qifTx.amount })
104	        .andWhere("linked.account_id = :linkedAccountId", {
105	          linkedAccountId: mappedTransferAccountId,
106	        })
107	        .getCount();
108	
109	      // Always count every QIF entry with this signature, even when
110	      // existingCount is zero (fresh import). This ensures that when the
111	      // next entry with the same signature arrives and finds existingCount=1,
112	      // seenSoFar is already 1 so seenSoFar+1=2 > 1 and it is not
113	      // incorrectly skipped. Matches processCashTransfer counting logic.
