272	 * reaching the same row cannot both claim it; the one that loses writes the
273	 * line as a new row, which the unique index then refuses if the winner holds
274	 * the same bank id (`isExternalIdConflict` in the import loop).
275	 */
276	export async function adoptKeyOnRecordedTransfer(
277	  ctx: ImportContext,
278	  qifTx: any,
279	  externalId: string,
280	): Promise<boolean> {
281	  if (!qifTx.isTransfer) return false;
282	  const rowId = await recordedTransferWithoutKey(ctx, qifTx);
283	  if (!rowId) return false;
284	  const result = await ctx.manager
285	    .createQueryBuilder()
286	    .update(Transaction)
287	    .set({ externalId })
288	    .where("id = :id", { id: rowId })
289	    .andWhere("external_id IS NULL")
290	    .execute();
291	  if (!result.affected) return false;
292	  holdKey(ctx.heldExternalIds, externalId, qifTx);
293	  return true;
294	}

