     2	 * Rewrite an imported amount's grouping and decimal separators to the
     3	 * `parseFloat` form: grouping removed, decimal separator a dot. The input has
     4	 * already had its currency symbols and whitespace stripped.
     5	 *
     6	 * The convention is inferred from the value itself, because neither the CSV
     7	 * nor the QIF import is told which one the file uses:
     8	 *
     9	 *   - comma and dot both present: whichever appears last is the decimal
    10	 *     separator ("1.234,56", "1,234.56");
    11	 *   - only commas: one comma is a decimal comma ("18,36", "0,125") unless it
    12	 *     groups a non-zero integer part into exactly three digits ("1,234"), and
    13	 *     several commas are grouping ("1,234,567");
    14	 *   - only dots: one dot is a decimal point ("1.234"), several are grouping
    15	 *     ("1.234.567").
    16	 *
    17	 * The one ambiguous shape, a single separator followed by exactly three digits
    18	 * on a non-zero integer part, keeps the US reading it had before the European
    19	 * forms were recognised.
    20	 */
    21	export function normalizeAmountSeparators(value: string): string {
    22	  const commaCount = countOf(value, ",");
    23	  const dotCount = countOf(value, ".");
