 16	/**
 17	 * Mean length of one cycle of each frequency, in days. `ONCE` is 0 -- it has no
 18	 * cycle, and callers matching an observed or computed spacing must skip it.
 19	 *
 20	 * Means, not whole cycles: a value here is matched against a number of days, so
 21	 * February and a 31-day month have to average out rather than round up. That is
 22	 * why the calendar frequencies are written as fractions of `365.25` -- the
 23	 * spellings are chosen so that a cadence expressed as "one <unit> divided by n
 24	 * occurrences" lands on exactly one of these numbers rather than near it, which
 25	 * is what lets a code table be matched by equality instead of by tolerance.
 26	 *
 27	 * This is the one place a frequency's length is written down. The `.mny`
 28	 * importer reads it from both ends -- `bill-cadence.ts` matches observed
 29	 * instance spacing against it, `mny-model.ts` matches Money's own recurrence
 30	 * codes against it -- and the compiler forces a new frequency to declare one.
 31	 */
 32	export const FREQUENCY_CYCLE_DAYS: Record<FrequencyType, number> = {
 33	  ONCE: 0,
 34	  DAILY: 1,
 35	  WEEKLY: 7,
 36	  BIWEEKLY: 14,
 37	  EVERY4WEEKS: 28,
 38	  SEMIMONTHLY: 365.25 / 24,
 39	  MONTHLY: 365.25 / 12,
 40	  EVERY2MONTHS: 365.25 / 6,
 41	  QUARTERLY: 365.25 / 4,
 42	  EVERY4MONTHS: 365.25 / 3,
 43	  SEMIANNUAL: 365.25 / 2,
 44	  YEARLY: 365.25,
 45	  EVERY2YEARS: 365.25 * 2,
 46	};
