 50	function parseYMD(ymd: string): { y: number; m: number; d: number } {
 51	  const match = YMD_PATTERN.exec(ymd);
 52	  if (!match) {
 53	    throw new Error(`Invalid YYYY-MM-DD date string: ${ymd}`);
 54	  }
 55	  return {
 56	    y: Number(match[1]),
 57	    m: Number(match[2]),
 58	    d: Number(match[3]),
 59	  };
 60	}
