 71	function addDays(ymd: string, days: number): string {
 72	  const { y, m, d } = parseYMD(ymd);
 73	  const next = new Date(Date.UTC(y, m - 1, d + days));
 74	  return formatYMD(
 75	    next.getUTCFullYear(),
 76	    next.getUTCMonth() + 1,
 77	    next.getUTCDate(),
 78	  );
 79	}
