 88	 * stored term_end_date skipped February and differed by a day between
 89	 * deployments.
 90	 */
 91	export function addMonthsClamped(
 92	  ymd: string,
 93	  months: number,
 94	  anchorDay?: number,
 95	): string {
 96	  const { y, m, d: prevDay } = parseYMD(ymd);
 97	  const d = anchorDay ?? prevDay;
 98	  const total = y * 12 + (m - 1) + months;
 99	  const ny = Math.floor(total / 12);
100	  const nm = (total % 12) + 1;
101	  const nd = Math.min(d, daysInMonth(ny, nm));
102	  return formatYMD(ny, nm, nd);
103	}
