 97	  const d = anchorDay ?? prevDay;
 98	  const total = y * 12 + (m - 1) + months;
 99	  const ny = Math.floor(total / 12);
100	  const nm = (total % 12) + 1;
101	  const nd = Math.min(d, daysInMonth(ny, nm));
102	  return formatYMD(ny, nm, nd);
103	}
104	
105	function addYearsClamped(
106	  ymd: string,
107	  years: number,
108	  anchorDay?: number,
109	): string {
110	  const { y, m, d: prevDay } = parseYMD(ymd);
111	  const d = anchorDay ?? prevDay;
112	  const ny = y + years;
113	  const nd = Math.min(d, daysInMonth(ny, m));
114	  return formatYMD(ny, m, nd);
115	}
116	
117	/**
118	 * The date after `ymd`. `anchorDay` is the day-of-month of the schedule's
119	 * `start_date`: a month-based step clamps to the month length but returns to
120	 * the anchor day afterwards (31 Jan -> 28 Feb -> 31 Mar). Without it the step
121	 * keeps the previous date's day, which drifts after a short month.
122	 */
123	export function calculateNextDueDate(
124	  ymd: string,
125	  frequency: FrequencyType,
126	  anchorDay?: number,
127	): string {
128	  switch (frequency) {
129	    case "ONCE":
130	      return ymd;
131	    case "DAILY":
132	      return addDays(ymd, 1);
133	    case "WEEKLY":
134	      return addDays(ymd, 7);
135	    case "BIWEEKLY":
136	      return addDays(ymd, 14);
137	    case "EVERY4WEEKS":
138	      return addDays(ymd, 28);
139	    case "SEMIMONTHLY": {
140	      const { y, m, d } = parseYMD(ymd);
141	      if (d <= 15) {
142	        return formatYMD(y, m, daysInMonth(y, m));
143	      }
144	      const total = y * 12 + m;
145	      const ny = Math.floor(total / 12);
146	      const nm = (total % 12) + 1;
147	      return formatYMD(ny, nm, 15);
148	    }
149	    case "MONTHLY":
150	      return addMonthsClamped(ymd, 1, anchorDay);
151	    case "EVERY2MONTHS":
152	      return addMonthsClamped(ymd, 2, anchorDay);
153	    case "QUARTERLY":
154	      return addMonthsClamped(ymd, 3, anchorDay);
155	    case "EVERY4MONTHS":
156	      return addMonthsClamped(ymd, 4, anchorDay);
157	    case "SEMIANNUAL":
158	      return addMonthsClamped(ymd, 6, anchorDay);
159	    case "YEARLY":
160	      return addYearsClamped(ymd, 1, anchorDay);
161	    case "EVERY2YEARS":
162	      return addYearsClamped(ymd, 2, anchorDay);
163	    default:
164	      return ymd;
165	  }
166	}
167	
168	/**
169	 * The anchor day for stepping from `current`: the `start_date`'s day when
170	 * `current` sits on it (or on it clamped by a short month), else `current`'s own
171	 * day because the user moved it. Undefined without a `start_date`.
172	 */
173	export function anchorDayOf(
174	  startDate: string | Date | null | undefined,
175	  current: string | Date,
176	): number | undefined {
177	  if (!startDate) return undefined;
178	  const { d: s } = parseYMD(ensureYMD(startDate));
179	  const { y, m, d } = parseYMD(ensureYMD(current));
180	  return d === Math.min(s, daysInMonth(y, m)) ? s : d;
181	}
182	
183	export function ensureYMD(value: string | Date): string {
184	  if (typeof value === "string") {
185	    if (YMD_PATTERN.test(value)) return value;
186	    return value.split("T")[0];
187	  }
188	  const y = value.getUTCFullYear();
189	  const m = String(value.getUTCMonth() + 1).padStart(2, "0");
190	  const d = String(value.getUTCDate()).padStart(2, "0");
191	  return `${y}-${m}-${d}`;
192	}

