      { id: "legB", accountId: "sav", amount: 100, status: "RECONCILED", reconciledDate: "2026-10-31", linkedTransactionId: "legA", isSplit: false, transactionDate: "2026-10-01" },
    ],
    balances: [["chq", 900], ["sav", 1100]],
  });
